-- GENERATED by `wfj generate` from data/gossip/gossip-61.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["61062abc963f5fd0"] = { "Mi rincresce dirti che non posso aiutarti, <nobile/gentile> <signore/dama>, finché non saprai di più sulla conciatura. Parla invece con Faldron o Darianna, qui. Possono insegnarti l'abilità che ti serve.", "." },
  ["6108fbcddf000598"] = { "Quando incontrò i profughi al Muro dei Mantogrigio, sentì il dovere di soccorrerli, e mandò la sua donna a ⟦Hillsbrad=Colletorto⟧.", "." },
  ["611e541c424fa71b"] = { "L'anziano Darkcore si trova a ⟦Undercity=Sepulcra⟧.", "." },
  ["612729c279c4216c"] = { "Salvami...", "." },
  ["612c58b691980155"] = { "<Amico/Amica>, ⟦Stormwind=Roccavento⟧ ha bisogno del tuo aiuto e della tua generosità!\n\nLe nostre scorte di tessuti, un tempo abbondanti, sono ormai pericolosamente basse. ⟦Stormwind=Roccavento⟧ è impegnata su più fronti per ricostituire quelle riserve per la produzione di tessuti e bende! Una tua donazione di stoffa aiuterebbe immensamente ⟦Stormwind=Roccavento⟧ e ti farebbe guadagnare il rispetto dei cittadini!", "." },
  ["612fd2a00b0f13c6"] = { "Presto la tua sete di distruzione sarà placata.", "." },
  ["6131c669c8b9cf72"] = { "Cosa?! Tu non può battere me! Io tornerà!", "." },
  ["6132fd205eb53559"] = { "Il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧ protegge il fianco orientale del ⟦Field of Strife=Pian della Discordia⟧.\n\nNon è controllato da nessuna delle due parti.", "." },
  ["6149408c4b6ac142"] = { "%s si divide in due nuove Creature di Lava!", "." },
  ["614d74bbeb5971f4"] = { "La legione dei ⟦Blackrock=Roccianera⟧ arriva, nanetti! Bruceremo la terra e daremo fuoco ai cieli. Nessuno sopravvivrà...", "." },
  ["614dee05a9d7ceb5"] = { "Tutti sapranno ciò che è accaduto qui, in questo tempio maledetto, <eroe/eroina>. Se ne scriverà nei libri di storia: racconti narrati come leggende da Azeroth fino ai più remoti confini del Nether stesso!", "." },
  ["614fcd9234840356"] = { "%s pungola ripetutamente la pecora lanosa.", "." },
  ["615072776f75f85b"] = { "Quasi a ⟦Ratchet=Porto Paranco⟧! Manteniamo il ritmo...", "." },
  ["6154a76afe4581b5"] = { "%s sbriciola la lacrima in una ciotola di stufato.", "." },
  ["6156703ef38f566d"] = { "Fai un buon lavoro, ma è ancora un po' grezzo. Non preoccuparti, migliorerà con la pratica. A proposito, che ne dici se vediamo a cosa hai lavorato?", "." },
  ["615ef8d5d985aed4"] = { "Dimmi di più su queste Carte di Lunacupa.", "." },
  ["616f9e8a344d01db"] = { "Il lamento funebre di %s ha risvegliato il vicino alveare dei silitidi!", "." },
  ["61703eaa11897829"] = { "Salve, {class}. Di certo non serve che ti spieghi la gravità della nostra situazione qui. Dobbiamo raccogliere molti beni e, nella maggior parte dei casi, trasformarli in materiale bellico da trasportare alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧. Non è un'impresa da poco.\n\nDi recente, nel ⟦Molten Core=Nucleo Ardente⟧, abbiamo scoperto una cosa chiamata Pietra del Nucleo Carbonizzata. I nostri fabbri e ingegneri dicono di poterle usare bene, quindi ne sto supervisionando la raccolta qui. Al momento, su $2110w necessarie, siamo riusciti a raccoglierne $2108w.", "." },
  ["6173f2ea69723317"] = { "{name} ha assaltato la fattoria!", "." },
  ["6174f7f842c89f01"] = { "Schiena dritta! La tua debolezza mi disgusta!", "." },
  ["617c25ac3609a944"] = { "Non aspetteremo più dietro porte sbarrate e mura di pietra! Non ci sarà più negata la nostra vendetta! Persino i draghi tremeranno davanti alla nostra ira!", "." },
  ["6181b150085dea6b"] = { "Ahah, tu prendere in giro me, <amico/amica>. Pele'keiki sa che tu sai che noi dell'⟦Horde=Orda⟧ già avere tutta la roba di guerra che serve. Ora aspettiamo solo che quell'⟦Alliance=Alleanza⟧ prende la sua e poi cominciamo la guerra.", "." },
  ["6194b17a05733da3"] = { "Ehi, {name}. Qui, voglio parlarti.", "." },
  ["61955939760ceb0e"] = { "Saluti. La mia funzione è offrire accesso e, quando consentito, chiarimenti sulle informazioni riguardanti la sintesi dei Terrigeni a opera dei Creatori sul mondo designato come Azeroth. Posso condividere queste informazioni con te ora, quando preferisci.", "." },
  ["6195631e5db75799"] = { "Devi capire che poter indicizzare 10.000 anni di esistenza mi ha dato una prospettiva piuttosto unica sulla vita. Le tue prove e tribolazioni di oggi non hanno alcun significato.", "." },
  ["6198903834732a24"] = { "D'accordo, allora... Conosco la strada per andare e tornare da ⟦Gadgetzan=Meccania⟧. Quello che ti chiedo è di tenere lontane le bestie. Ho addestrato Dadanga a difendersi piuttosto bene, ma non possiamo reggere a lungo contro quella follia rigogliosa là fuori. Fammi sapere quando sei <pronto/pronta> a partire, {name}.", "." },
  ["61a43cc6c437a5f8"] = { "Raggiungiamo gli altri, e occhio a quei lupi là fuori...", "." },
  ["61b2a38a06a0f52a"] = { "Questo è ⟦Dalin Forgewright=Dalin Forgiabruna⟧. Fuggì da Lordaeron quando colpì la peste, portando con sé la sua amata.", "." },
  ["61b376694c3080e5"] = { "Cosa sono le professioni?", "." },
  ["61b7b41698bdfdc3"] = { "Ti insegnerò la via del fabbro di martelli. Basta chiedere con gentilezza.", "." },
  ["61d1a8a81fd692f9"] = { "I morti camminano tra noi!", "." },
  ["61d8c94fe553b01d"] = { "%s abbocca ed esce allo scoperto!", "." },
  ["61dfc5c2ceb6a69b"] = { "⟦Yaw Sharpmane=Yaw Chioma Rasa⟧ ti aspetta sul margine nord del villaggio. Può insegnarti le vie del Cacciatore.", "." },
  ["61e7b28d9be5da4a"] = { "Sia lodata Elune! Sono passati molti anni dall'ultima volta che ho ricevuto visite.", "." },
  ["61ec9f54fb2be52c"] = { "Percorro questa strada in solitudine, cercando il modo di difendere il mio onore e di liberare questa terra dai nostri nemici.\n\nCosa posso fare per te, {name}?", "." },
  ["61f12c5455340c9d"] = { "L'⟦Alliance=Alleanza⟧ ha molti interessi in ⟦Desolace=Desolanda⟧, e la nostra presa qui è instabile.\n\nCi aiuterai?", "." },
  ["61f4210759c4586d"] = { "Gli umani di solito sono vulnerabili sul fianco sinistro, tra la 4ª e la 5ª costola. Esercitiamoci a colpire questo punto, così...", "." },
  ["61f45991a182f25f"] = { "Abbiamo una grossa scorta di materiali per ricostruire la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Ancora un po' e ne avremo abbastanza per ripararla e tornare in battaglia!", "." },
})
